/// The Qeetrix typography roles (`typography.*`). Raw values are the upstream role names.
public enum QeetrixTextRole: String, CaseIterable, Sendable {
    /// `typography.display.*` · `--qx-typography-display-*`
    ///
    /// Qeet Sans, 48 pt, weight 600, line height 1.2×.
    case display

    /// `typography.heading.*` · `--qx-typography-heading-*`
    ///
    /// Qeet Sans, 20 pt, weight 600, line height 1.2×.
    case heading

    /// `typography.title.*` · `--qx-typography-title-*`
    ///
    /// Qeet Sans, 32 pt, weight 600, line height 1.2×.
    case title

    /// `typography.body.*` · `--qx-typography-body-*`
    ///
    /// Qeet Sans, 14 pt, weight 400, line height 1.5×.
    case body

    /// `typography.label.*` · `--qx-typography-label-*`
    ///
    /// Qeet Sans, 13 pt, weight 500, line height 1.35×.
    case label

    /// `typography.label-compact.*` · `--qx-typography-label-compact-*`
    ///
    /// Qeet Sans, 12.8 pt, weight 500, line height 1.35×.
    case labelCompact = "label-compact"

    /// `typography.caption.*` · `--qx-typography-caption-*`
    ///
    /// Qeet Sans, 12 pt, weight 400, line height 1.35×.
    case caption

    /// `typography.micro.*` · `--qx-typography-micro-*`
    ///
    /// Qeet Sans, 11 pt, weight 500, line height 1.35×.
    case micro

    /// `typography.code.*` · `--qx-typography-code-*`
    ///
    /// Fira Code, 13 pt, weight 400, line height 1.5×.
    case code

    /// The role's token values.
    public var tokens: QeetrixTextRoleTokens {
        switch self {
        case .display:
            QeetrixTextRoleTokens(
                family: .sans, size: 48, weight: .semibold,
                lineHeight: 1.2, letterSpacing: 0, geometry: .base)
        case .heading:
            QeetrixTextRoleTokens(
                family: .sans, size: 20, weight: .semibold,
                lineHeight: 1.2, letterSpacing: 0, geometry: .base)
        case .title:
            QeetrixTextRoleTokens(
                family: .sans, size: 32, weight: .semibold,
                lineHeight: 1.2, letterSpacing: 0, geometry: .base)
        case .body:
            QeetrixTextRoleTokens(
                family: .sans, size: 14, weight: .regular,
                lineHeight: 1.5, letterSpacing: 0, geometry: .ui)
        case .label:
            QeetrixTextRoleTokens(
                family: .sans, size: 13, weight: .medium,
                lineHeight: 1.35, letterSpacing: 0, geometry: .ui)
        case .labelCompact:
            QeetrixTextRoleTokens(
                family: .sans, size: 12.8, weight: .medium,
                lineHeight: 1.35, letterSpacing: 0, geometry: .ui)
        case .caption:
            QeetrixTextRoleTokens(
                family: .sans, size: 12, weight: .regular,
                lineHeight: 1.35, letterSpacing: 0, geometry: .ui)
        case .micro:
            QeetrixTextRoleTokens(
                family: .sans, size: 11, weight: .medium,
                lineHeight: 1.35, letterSpacing: 0, geometry: .ui)
        case .code:
            QeetrixTextRoleTokens(
                family: .mono, size: 13, weight: .regular,
                lineHeight: 1.5, letterSpacing: 0, geometry: nil)
        }
    }
}

/// The bundled typefaces. Each is the native TTF of the exact font the web ships as WOFF2.
public enum QeetrixFontFamily: String, CaseIterable, Sendable {
    /// Qeet Sans on the web: Cal Sans, Version 2.011; 5a149ee7 (calcom/sans v2.011).
    case sans

    /// Fira Code on the web: Fira Code, Version 6.002 (tonsky/FiraCode 6.2).
    case mono

    /// The bundled font file and its variation axes, as read from the font at generation time.
    public var face: QeetrixFontFace {
        switch self {
        case .sans:
            QeetrixFontFace(
                resourceName: "CalSansVF",
                postScriptName: "CalSans-Regular",
                familyName: "Cal Sans",
                webFamily: "Qeet Sans",
                axes: [
                    QeetrixFontAxis(tag: "opsz", minimum: 8, defaultValue: 14, maximum: 45),
                    QeetrixFontAxis(tag: "GEOM", minimum: 0, defaultValue: 25, maximum: 100),
                    QeetrixFontAxis(tag: "wght", minimum: 400, defaultValue: 400, maximum: 700),
                    QeetrixFontAxis(tag: "YTAS", minimum: 1440, defaultValue: 1440, maximum: 1600),
                    QeetrixFontAxis(tag: "SHRP", minimum: 0, defaultValue: 0, maximum: 100),
                    QeetrixFontAxis(tag: "ital", minimum: 0, defaultValue: 0, maximum: 1)
                ])
        case .mono:
            QeetrixFontFace(
                resourceName: "FiraCode-VF",
                postScriptName: "FiraCode-Light",
                familyName: "Fira Code",
                webFamily: "Fira Code",
                axes: [
                    QeetrixFontAxis(tag: "wght", minimum: 300, defaultValue: 300, maximum: 700)
                ])
        }
    }
}
